    21	function stats(ctx: Ctx, a: number) {
    22	  const m = ctx.emu.mem, be = (o: number) => (m[a + o] << 8) | m[a + o + 1];
    23	  return { level: m[a + 14], atk: be(17), def: be(19), spd: be(21), spc: be(23) };
