    49	  const species = (rows[1] ?? '').slice(4).replace(/[^A-Z0-9♂♀.\- ]/g, '').trim() || 'the new Pokémon';
    50	  // the name must be made up: not a species name, not a nickname already in use (party or current PC box)
    51	  const taken = new Set<string>([...ctx.rom.species.values()].map((sp) => sp.name));
    52	  for (const p of ctx.gs.party()) taken.add(p.nickname);
    53	  const boxCount = Math.min(ctx.gs.u8('wBoxCount'), 20);
    54	  for (let i = 0; i < boxCount; i++) taken.add(decode(ctx.emu.mem, sym('wBoxMonNicks') + i * 11, 11));
    55	  let name = '';
    56	  for (let guard = 0; guard < 40 && name.length <= MAX_NICK; guard++) {
    57	    if (name.length === MAX_NICK) { if (!taken.has(name)) break; name = name.slice(0, -1); } // full but taken: change the end
    58	    const options: Record<string, string> = {};
    59	    // shuffled, so the list order doesn't favor A, B, C...
    60	    for (const l of [...LETTERS].sort(() => Math.random() - 0.5)) options[l] = `Name becomes "${name}${l}".${taken.has(name + l) ? ' That is an existing Pokémon name or nickname, so it cannot be the final name.' : ''}`;
    61	    if (name && !taken.has(name)) options.DONE = `Finish: the nickname is "${name}".`;
    62	    const { answers } = await ctx.jev.ask('nickname', { species, types: speciesTypes, nameSoFar: name, lettersLeft: MAX_NICK - name.length }, {
    63	      letter: { type: 'choice', criteria: options,
    64	        instructions: `Give ${species}${speciesTypes ? ` (${speciesTypes} type)` : ''} a nickname, one letter at a time. Rule: it must be a new, made-up name, not the name of any Pokémon species and not a nickname already in use. Name so far: "${name}". Pick the next letter${options.DONE ? ', or DONE to finish' : ''}. Up to ${MAX_NICK} letters.` },
    65	    });
    66	    // draw from Jev's distribution (the top choice alone tends to spell the alphabet in order)
    67	    const probs = Object.entries(((answers as any)?.letter?.probabilities ?? {}) as Record<string, number>).filter(([k]) => k in options);
    68	    let r = Math.random() * probs.reduce((a, [, p]) => a + p, 0), pick = probs[0]?.[0] ?? 'DONE';
    69	    for (const [k, p] of probs) { r -= p; if (r <= 0) { pick = k; break; } }
    70	    if (pick === 'DONE') break;
    71	    if (LETTERS.includes(pick)) name += pick;
    72	  }
    73	  if (!name || taken.has(name)) name = (name || 'X').slice(0, MAX_NICK - 1) + 'X'; // safety net, should not happen
