    49	   * (joypad direction, count) pairs. The game plays simulated joypad states back to front, so the list is reversed.
    50	   */
    51	  private loadSpinners() {
    52	    const tables: [string, string][] = [
    53	      ['RocketHideout2ArrowTilePlayerMovement', 'ROCKET_HIDEOUT_B2F'],
    54	      ['RocketHideout3ArrowTilePlayerMovement', 'ROCKET_HIDEOUT_B3F'],
    55	      ['ViridianGymArrowTilePlayerMovement', 'VIRIDIAN_GYM'],
    56	    ];
    57	    const PAD: Record<number, [number, number]> = { 0x10: [1, 0], 0x20: [-1, 0], 0x40: [0, -1], 0x80: [0, 1] };
    58	    for (const [symName, mapNameStr] of tables) {
    59	      const mapId = +(Object.entries(MAPS).find(([, v]) => v.name === mapNameStr)?.[0] ?? -1);
    60	      let a: number;
    61	      try { a = sym(symName); } catch { continue; }
    62	      const bank = Math.floor(a / 0x4000);
    63	      const out = new Map<string, { x: number; y: number }>();
    64	      for (; this.b[a] !== 0xff; a += 4) {
    65	        const y = this.b[a], x = this.b[a + 1];
    66	        const moves: [number, number][] = [];
    67	        for (let m = this.flat(bank, this.u16(a + 2)); this.b[m] !== 0xff; m += 2) moves.push([this.b[m], this.b[m + 1]]);
    68	        let px = x, py = y;
    69	        for (const [pad, n] of moves.reverse()) { const d = PAD[pad]; if (d) { px += d[0] * n; py += d[1] * n; } }
    70	        out.set(`${x},${y}`, { x: px, y: py });
    71	      }
    72	      this.spinners.set(mapId, out);
    73	    }
    74	  }
    75	
    76	  /** Move taught by a TM/HM item id (or null). */
    77	  machineMove(itemId: number): MoveData | null {
    78	    const idx = itemId >= 0xc9 ? itemId - 0xc9 : itemId >= 0xc4 ? 50 + itemId - 0xc4 : -1;
    79	    return idx >= 0 ? this.moves.get(this.tmMoves[idx]) ?? null : null;
    80	  }
    81	
    82	  private loadHidden() {
    83	    const names = new Map<number, string>();
    84	    for (const [n, a] of Object.entries(symbols())) if (a >= 0x4000 && !n.includes('.')) names.set(a, n);
    85	    const maps = sym('HiddenEventMaps'), ptrs = sym('HiddenEventPointers');
    86	    const bank = Math.floor(maps / 0x4000);
    87	    for (let i = 0; this.b[maps + i] !== 0xff; i++) {
    88	      const list: { x: number; y: number; arg: number; fn: string }[] = [];
    89	      for (let a = this.flat(bank, this.u16(ptrs + i * 2)); this.b[a] !== 0xff; a += 6) {
    90	        const fnAddr = this.flat(this.b[a + 3], this.u16(a + 4));
    91	        list.push({ y: this.b[a], x: this.b[a + 1], arg: this.b[a + 2], fn: names.get(fnAddr) ?? 'Unknown' });
    92	      }
    93	      this.hidden.set(this.b[maps + i], list);
    94	    }
    95	  }
    96	
    97	  u8(a: number) { return this.b[a]; }
    98	  u16(a: number) { return this.b[a] | (this.b[a + 1] << 8); }
    99	  /** Resolve a banked pointer to a flat ROM offset. */
   100	  flat(bank: number, ptr: number) { return ptr < 0x4000 ? ptr : bank * 0x4000 + (ptr - 0x4000); }
   101	
   102	  private strings(start: number, count: number): string[] {
   103	    const out: string[] = [];
   104	    let a = start;
   105	    for (let i = 0; i < count; i++) {
   106	      out.push(decode(this.b, a, 32));
   107	      while (this.b[a] !== 0x50) a++;
   108	      a++;
   109	    }
   110	    return out;
   111	  }
   112	
   113	  private loadMoves() {
   114	    const names = this.strings(sym('MoveNames'), 165);
   115	    const base = sym('Moves');
   116	    for (let i = 0; i < 165; i++) {
   117	      const a = base + i * 6;
   118	      this.moves.set(i + 1, {
   119	        id: i + 1, name: names[i], effect: this.b[a + 1], power: this.b[a + 2],
   120	        type: TYPE_NAMES[this.b[a + 3]] ?? '?', accuracy: Math.round((this.b[a + 4] / 255) * 100), pp: this.b[a + 5],
   121	      });
   122	    }
   123	  }
   124	
   125	  private loadItems() {
   126	    const names = this.strings(sym('ItemNames'), 97);
   127	    names.forEach((n, i) => this.items.set(i + 1, n));
   128	    for (let i = 1; i <= 5; i++) this.items.set(0xc3 + i, `HM0${i}`);
   129	    for (let i = 1; i <= 50; i++) this.items.set(0xc8 + i, `TM${String(i).padStart(2, '0')}`);
   130	  }
   131	
   132	  private loadSpecies() {
   133	    const namesAt = sym('MonsterNames');
   134	    const dexOrder = sym('PokedexOrder');
   135	    for (let id = 1; id <= 190; id++) {
   136	      const dex = this.b[dexOrder + id - 1];
   137	      if (!dex) continue;
   138	      const a = dex === 151 ? sym('MewBaseStats') : sym('BaseStats') + (dex - 1) * 28;
   139	      const t1 = TYPE_NAMES[this.b[a + 6]], t2 = TYPE_NAMES[this.b[a + 7]];
   140	      this.species.set(id, {
   141	        id, dex, name: decode(this.b, namesAt + (id - 1) * 10, 10),
   142	        types: t1 === t2 ? [t1] : [t1, t2],
   143	        base: { hp: this.b[a + 1], atk: this.b[a + 2], def: this.b[a + 3], spd: this.b[a + 4], spc: this.b[a + 5] },
   144	        catchRate: this.b[a + 8],
   145	        tmhm: this.b.slice(a + 20, a + 27),
   146	        stoneEvos: this.stoneEvolutions(id),
   147	      });
   148	    }
   149	  }
   150	
   151	  /** Items (evolution stones) that evolve this species, from EvosMovesPointerTable. */
   152	  private stoneEvolutions(id: number): number[] {
   153	    const table = sym('EvosMovesPointerTable');
   154	    const bank = Math.floor(table / 0x4000);
   155	    let a = this.flat(bank, this.u16(table + (id - 1) * 2));
   156	    const out: number[] = [];
   157	    for (let guard = 0; this.b[a] !== 0 && guard < 8; guard++) {
   158	      const method = this.b[a];
   159	      if (method === 1) a += 3;                                  // EVOLVE_LEVEL, level, species
   160	      else if (method === 2) { out.push(this.b[a + 1]); a += 4; } // EVOLVE_ITEM, item, 1, species
   161	      else if (method === 3) a += 3;                             // EVOLVE_TRADE, 1, species
   162	      else break;
   163	    }
   164	    return out;
   165	  }
   166	
   167	  /** All evolutions of a species: by level, by item (stone) or by trade, with the species it becomes. */
   168	  evolutions(id: number): { method: 'level' | 'item' | 'trade'; level?: number; item?: number; into: number }[] {
   169	    const table = sym('EvosMovesPointerTable');
   170	    const bank = Math.floor(table / 0x4000);
   171	    let a = this.flat(bank, this.u16(table + (id - 1) * 2));
   172	    const out: { method: 'level' | 'item' | 'trade'; level?: number; item?: number; into: number }[] = [];
   173	    for (let guard = 0; this.b[a] !== 0 && guard < 8; guard++) {
   174	      const method = this.b[a];
   175	      if (method === 1) { out.push({ method: 'level', level: this.b[a + 1], into: this.b[a + 2] }); a += 3; }
   176	      else if (method === 2) { out.push({ method: 'item', item: this.b[a + 1], into: this.b[a + 3] }); a += 4; }
   177	      else if (method === 3) { out.push({ method: 'trade', into: this.b[a + 2] }); a += 3; }
   178	      else break;
   179	    }
   180	    return out;
   181	  }
   182	
   183	  /** Can this species learn the TM/HM item? (bit n of the tmhm flags = machine n+1) */
   184	  canLearnMachine(speciesId: number, itemId: number): boolean {
   185	    const idx = itemId >= 0xc9 ? itemId - 0xc9 : itemId >= 0xc4 ? 50 + itemId - 0xc4 : -1;
   186	    const sp = this.species.get(speciesId);
   187	    return !!sp && idx >= 0 && !!(sp.tmhm[idx >> 3] & (1 << (idx & 7)));
   188	  }
   189	
   190	  private loadTypeChart() {
   191	    for (let a = sym('TypeEffects'); this.b[a] !== 0xff; a += 3) {
   192	      this.typeChart.set(`${TYPE_NAMES[this.b[a]]}>${TYPE_NAMES[this.b[a + 1]]}`, this.b[a + 2] / 10);
   193	    }
   194	  }
   195	
   196	  effectiveness(moveType: string, defTypes: string[]): number {
   197	    return defTypes.reduce((m, t) => m * (this.typeChart.get(`${moveType}>${t}`) ?? 1), 1);
   198	  }
   199	
   200	  private loadMaps() {
   201	    const banks = sym('MapHeaderBanks'), ptrs = sym('MapHeaderPointers');
   202	    for (const [idStr, meta] of Object.entries(MAPS)) {
   203	      const id = +idStr;
   204	      if (meta.name.startsWith('UNUSED')) continue;
   205	      const bank = this.b[banks + id];
   206	      let h = this.flat(bank, this.u16(ptrs + id * 2));
   207	      const tileset = this.b[h], height = this.b[h + 1], width = this.b[h + 2];
   208	      const blocksPtr = this.u16(h + 3);
   209	      const flags = this.b[h + 9];
   210	      h += 10;
   211	      const connections: Connection[] = [];
   212	      for (const [bit, dir] of [[3, 'north'], [2, 'south'], [1, 'west'], [0, 'east']] as const) {
   213	        if (flags & (1 << bit)) {
   214	          const y = this.b[h + 7], x = this.b[h + 8];
   215	          connections.push({ dir, map: this.b[h], yAlign: y > 127 ? y - 256 : y, xAlign: x > 127 ? x - 256 : x });
   216	          h += 11;
   217	        }
   218	      }
   219	      let o = this.flat(bank, this.u16(h));
   220	      o++; // border block
   221	      const warps: Warp[] = [];
   222	      for (let n = this.b[o++], i = 0; i < n; i++, o += 4) warps.push({ y: this.b[o], x: this.b[o + 1], destWarp: this.b[o + 2], destMap: this.b[o + 3] });
   223	      const signs: Sign[] = [];
   224	      for (let n = this.b[o++], i = 0; i < n; i++, o += 3) signs.push({ y: this.b[o], x: this.b[o + 1], textId: this.b[o + 2] });
   225	      const objects: MapObject[] = [];
   226	      for (let n = this.b[o++], i = 0; i < n; i++) {
   227	        const sprite = this.b[o], y = this.b[o + 1] - 4, x = this.b[o + 2] - 4, movement = this.b[o + 3], t = this.b[o + 5];
   228	        let item: number | null = null, trainer = false;
   229	        let trainerClass: string | undefined;
   230	        if (t & 0x40) { trainer = true; const cls = this.b[o + 6] - 200; trainerClass = this.trainerNames[cls - 1]; o += 8; }
   231	        else if (t & 0x80) { item = this.b[o + 6]; o += 7; }
   232	        else o += 6;
   233	        objects.push({ index: i + 1, sprite, x, y, movement, textId: t & 0x3f, trainer, item, trainerClass });
   234	      }
   235	      this.maps.set(id, { id, name: meta.name, tileset, width, height, blocksPtr, bank, connections, warps, signs, objects });
   236	    }
   237	  }
   238	}

