   149	      const picture = this.m[sym('wSpriteStateData1') + i * 16];
   150	      const y = this.m[sym('wSpriteStateData2') + i * 16 + 4] - 4;
   151	      const x = this.m[sym('wSpriteStateData2') + i * 16 + 5] - 4;
   152	      out.push({ index: i, x, y, hidden: hiddenIdx.has(i) || picture === 0, picture });
