    18	  // Only type if the name field is empty (otherwise accept what's there). The field is row 2 from column 10
    19	  // on both the player/rival and the nickname screens (naming_screen.asm).
    20	  const typed = (rows()[2] ?? '').slice(10).trim();
    21	  if (typed.replace(/[_\s]/g, '')) { tap(ctx, 'START', 20); return; }
