   123	      const eff = (ts: string[]) => Math.max(0, ...p.moves.filter((mv) => mv.power > 0).map((mv) => ctx.rom.effectiveness(mv.type, ts)));
   124	      const best = m.dualType ? eff(m.types!) : Math.max(...m.types!.map((t) => eff([t])));
