     5	// Mechanical helpers for the START menu. What to use and when is always Jev's call.
     6	
     7	export function openStart(ctx: Ctx): boolean {
     8	  for (let i = 0; i < 3; i++) {
     9	    tap(ctx, 'START', 20);
    10	    if (ctx.gs.screen().rows.some((r) => r.includes('EXIT'))) return true;
    11	  }
