    32	/** START → ITEM → item → USE. Follow-up prompts (which Pokémon, forget which move...) go through the normal Jev menu loop. */
    33	export function useItem(ctx: Ctx, item: string): boolean {
    34	  ctx.mem.lastItem = item;
    35	  if (!openStart(ctx) || !select(ctx, 'ITEM')) { closeMenus(ctx); return false; }
    36	  ctx.emu.wait(20);
    37	  if (!cursorTo(ctx, item)) { closeMenus(ctx); return false; }
    38	  const before = ctx.gs.screen().rows.join('');
    39	  tap(ctx, 'A', 4);
    40	  waitForChange(ctx, before, 40);
    41	  if (ctx.gs.screen().rows.some((r) => r.includes('USE'))) select(ctx, 'USE');
