     4	
     5	// Mechanical helpers for the START menu. What to use and when is always Jev's call.
     6	
     7	export function openStart(ctx: Ctx): boolean {
     8	  for (let i = 0; i < 3; i++) {
     9	    tap(ctx, 'START', 20);
    10	    if (ctx.gs.screen().rows.some((r) => r.includes('EXIT'))) return true;
    11	  }
    12	  return false;
    13	}
    14	
    15	export function closeMenus(ctx: Ctx) {
    16	  for (let i = 0; i < 6 && ctx.gs.screen().nonMapTiles > 0; i++) tap(ctx, 'B', 12);
    17	}
    18	
    19	/** START → POKéMON → slot → field move (CUT/SURF/STRENGTH/FLASH/...). */
    20	export function useFieldMove(ctx: Ctx, slot: number, move: string): boolean {
    21	  if (!openStart(ctx) || !select(ctx, 'POKéMON')) { closeMenus(ctx); return false; }
    22	  ctx.emu.wait(20);
    23	  if (!cursorToIndex(ctx, slot)) { closeMenus(ctx); return false; }
    24	  const before = ctx.gs.screen().rows.join('');
    25	  tap(ctx, 'A', 4);
    26	  waitForChange(ctx, before, 40);
    27	  if (!select(ctx, move)) { closeMenus(ctx); return false; }
    28	  ctx.emu.wait(30);
    29	  return true;
    30	}
    31	
    32	/** START → ITEM → item → USE. Follow-up prompts (which Pokémon, forget which move...) go through the normal Jev menu loop. */
    33	export function useItem(ctx: Ctx, item: string): boolean {
    34	  ctx.mem.lastItem = item;
    35	  if (!openStart(ctx) || !select(ctx, 'ITEM')) { closeMenus(ctx); return false; }
    36	  ctx.emu.wait(20);
    37	  if (!cursorTo(ctx, item)) { closeMenus(ctx); return false; }
    38	  const before = ctx.gs.screen().rows.join('');
    39	  tap(ctx, 'A', 4);
    40	  waitForChange(ctx, before, 40);
    41	  if (ctx.gs.screen().rows.some((r) => r.includes('USE'))) select(ctx, 'USE');
