     1	import type { JevBackend, JevRequest, JevResult, JevAnswer } from './types.js';
     2	
     3	/**
     4	 * Development stand-in for Jev. Same request/response shape, zero cost.
     5	 * It has NO game knowledge: it scores choice options by generic sentiment
     6	 * words in the option descriptions the harness provides, plus noise.
     7	 * The real Jev replaces this 1:1 via JEV_MODE=gateway.
     8	 */
     9	const POS: [RegExp, number][] = [
    10	  [/toward (the )?objective|objective is here|completes objective/i, 3],
    11	  [/super effective/i, 2.5],
    12	  [/unvisited|never been|not yet talked|unexplored/i, 1],
    13	  [/heals|restore/i, 0.5],
    14	  [/likely KO|high damage/i, 1.5],
    15	  [/advances|confirm|continue/i, 0.5],
    16	];
    17	const NEG: [RegExp, number][] = [
    18	  [/no effect|immune/i, -5],
    19	  [/not very effective/i, -1.5],
    20	  [/away from (the )?objective|backtrack/i, -1.5],
    21	  [/0 PP|fainted|unusable/i, -6],
    22	  [/already visited|talked already|recently/i, -0.8],
    23	  [/risky|dangerous|low HP/i, -0.7],
    24	  [/cancel|go back/i, -0.5],
    25	];
    26	
    27	const text = (v: unknown) => (typeof v === 'string' ? v : JSON.stringify(v ?? ''));
    28	
    29	export class MockJev implements JevBackend {
    30	  name = 'mock';
    31	  constructor(private temperature = 0.6, private latencyMs = 0) {}
    32	
    33	  async evaluate(req: JevRequest): Promise<JevResult> {
    34	    if (this.latencyMs) await new Promise((r) => setTimeout(r, this.latencyMs));
    35	    const answers: Record<string, JevAnswer> = {};
    36	    let tokens = Math.ceil(text(req.state).length / 4);
    37	    for (const [id, q] of Object.entries(req.questions)) {
    38	      tokens += Math.ceil((text(q.instructions).length + text(q.criteria).length) / 4);
    39	      if (q.type === 'choice') {
    40	        const keys = Object.keys(q.criteria);
    41	        const logits = keys.map((k) => {
    42	          const d = `${k} ${text(q.criteria[k])}`;
    43	          let s = Math.random() * 0.6;
    44	          for (const [re, w] of [...POS, ...NEG]) if (re.test(d)) s += w;
    45	          return s / this.temperature;
    46	        });
    47	        const mx = Math.max(...logits);
    48	        const ex = logits.map((l) => Math.exp(l - mx));
    49	        const sum = ex.reduce((a, b) => a + b, 0);
    50	        const probabilities = Object.fromEntries(keys.map((k, i) => [k, ex[i] / sum]));
    51	        const choice = keys[ex.indexOf(Math.max(...ex))];
    52	        answers[id] = { type: 'choice', choice, probabilities };
    53	      } else if (q.type === 'boolean') {
    54	        answers[id] = { type: 'boolean', probability: 0.5 + (Math.random() - 0.5) * 0.2 };
    55	      } else {
    56	        const n = q.criteria.length;
    57	        answers[id] = { type: 'score', score: (n - 1) / 2 };
    58	      }
    59	    }
    60	    return { answers, usage: { inputTokens: tokens, outputTokens: 0 } };
    61	  }
    62	}

