    82	static void _freeTable(void* data) {
    83		struct Table* table = data;
    84	
    85		struct TableIterator iter;
    86		if (TableIteratorStart(table, &iter)) {
    87			do {
    88				struct mScriptCallbackInfo* info = TableIteratorGetValue(table, &iter);
    89				mScriptValueDeref(info->fn);
    90			} while (TableIteratorNext(table, &iter));
    91		}
    92	
    93		TableDeinit(table);
    94		free(table);
    95	}
    96	
    97	void mScriptContextInit(struct mScriptContext* context) {
    98	#ifdef USE_PTHREADS
    99		pthread_once(&_contextOnce, _createTLS);
   100	#elif _WIN32
   101		InitOnceExecuteOnce(&_contextOnce, _createTLS, NULL, 0);
   102	#endif
   103		HashTableInit(&context->rootScope, 0, (void (*)(void*)) mScriptValueDeref);
   104		HashTableInit(&context->engines, 0, _engineContextDestroy);
   105		mScriptListInit(&context->refPool, 0);
   106		TableInit(&context->weakrefs, 0, (void (*)(void*)) mScriptValueDeref);
   107		context->nextWeakref = 1;
   108		HashTableInit(&context->callbacks, 0, _freeTable);
   109		TableInit(&context->callbackId, 0, free);
   110		context->nextCallbackId = 1;
   111		context->constants = NULL;
   112		HashTableInit(&context->docstrings, 0, NULL);
   113		context->threadDepth = 0;
   114	}
   115	
   116	void mScriptContextDeinit(struct mScriptContext* context) {
   117		HashTableDeinit(&context->rootScope);
   118		mScriptContextDrainPool(context);
   119		HashTableDeinit(&context->weakrefs);
   120		mScriptListDeinit(&context->refPool);
   121		HashTableDeinit(&context->callbacks);
   122		TableDeinit(&context->callbackId);
   123		HashTableDeinit(&context->engines);
   124		HashTableDeinit(&context->docstrings);
   125	}
   126	
   127	void mScriptContextFillPool(struct mScriptContext* context, struct mScriptValue* value) {
   128		if (value->refs == mSCRIPT_VALUE_UNREF) {
   129			return;
   130		}
   131	
   132		struct mScriptValue* poolEntry = mScriptListAppend(&context->refPool);
   133		poolEntry->type = mSCRIPT_TYPE_MS_WRAPPER;
