   212	uint32_t mScriptContextSetWeakref(struct mScriptContext* context, struct mScriptValue* value) {
   213		mScriptValueRef(value);
   214		TableInsert(&context->weakrefs, context->nextWeakref, value);
   215	
   216		uint32_t nextWeakref = context->nextWeakref;
   217		++context->nextWeakref;
   218		while (TableLookup(&context->weakrefs, context->nextWeakref)) {
   219			++context->nextWeakref;
   220		}
   221		return nextWeakref;
   222	}
   223	
   224	struct mScriptValue* mScriptContextMakeWeakref(struct mScriptContext* context, struct mScriptValue* value) {
   225		uint32_t weakref = mScriptContextSetWeakref(context, value);
   226		mScriptValueDeref(value);
   227		value = mScriptValueAlloc(mSCRIPT_TYPE_MS_WEAKREF);
   228		value->value.u32 = weakref;
   229		return value;
   230	}
   231	
   232	struct mScriptValue* mScriptContextAccessWeakref(struct mScriptContext* context, struct mScriptValue* value) {
   233		if (value->type != mSCRIPT_TYPE_MS_WEAKREF) {
   234			return value;
   235		}
   236		return TableLookup(&context->weakrefs, value->value.u32);
   237	}
