   244		struct mScriptValue* poolEntry = mScriptListAppend(&context->refPool);
   245		poolEntry->type = mSCRIPT_TYPE_MS_WEAKREF;
   246		poolEntry->value.u32 = weakref;
   247		poolEntry->refs = mSCRIPT_VALUE_UNREF;
