   250	void mScriptContextTriggerCallback(struct mScriptContext* context, const char* callback, struct mScriptList* args) {
   251		struct Table* table = HashTableLookup(&context->callbacks, callback);
   252		if (!table) {
   253			return;
   254		}
   255		struct TableIterator iter;
   256		if (!TableIteratorStart(table, &iter)) {
   257			return;
   258		}
   259	
   260		struct UInt32List oneshots;
   261		UInt32ListInit(&oneshots, 0);
   262		do {
   263			struct mScriptFrame frame;
   264			struct mScriptCallbackInfo* info = TableIteratorGetValue(table, &iter);
   265			struct mScriptValue* fn = mScriptContextAccessWeakref(context, info->fn);
   266			if (fn) {
   267				mScriptFrameInit(&frame);
   268				if (args) {
   269					mScriptListCopy(&frame.stack, args);
   270				}
   271				mScriptContextInvoke(context, fn, &frame);
   272				mScriptFrameDeinit(&frame);
   273			}
   274	
   275			if (info->oneshot) {
   276				*UInt32ListAppend(&oneshots) = info->id;
   277			}
   278		} while (TableIteratorNext(table, &iter));
   279	
   280		size_t i;
   281		for (i = 0; i < UInt32ListSize(&oneshots); ++i) {
   282			mScriptContextRemoveCallback(context, *UInt32ListGetPointer(&oneshots, i));
   283		}
   284		UInt32ListDeinit(&oneshots);
   285	}
