   167	static struct json_object* _tableToJson(struct mScriptValue* rootVal) {
   168		bool ok = true;
   169	
   170		struct TableIterator iter;
   171		struct json_object* rootObj = json_object_new_object();
   172		if (mScriptTableIteratorStart(rootVal, &iter)) {
   173			do {
   174				struct mScriptValue* key = mScriptTableIteratorGetKey(rootVal, &iter);
   175				struct mScriptValue* value = mScriptTableIteratorGetValue(rootVal, &iter);
   176				const char* ckey;
   177				if (key->type == mSCRIPT_TYPE_MS_CHARP) {
   178					ckey = key->value.copaque;
   179				} else if (key->type == mSCRIPT_TYPE_MS_STR) {
   180					ckey = key->value.string->buffer;
   181				} else {
   182					ok = false;
   183					break;
   184				}
   185	
   186				struct json_object* obj;
   187				ok = mScriptStorageToJson(value, &obj);
   188	
   189				if (ok) {
   190	#if JSON_C_VERSION_NUM >= (13 << 8)
   191					ok = json_object_object_add(rootObj, ckey, obj) >= 0;
   192	#else
   193					json_object_object_add(rootObj, ckey, obj);
   194	#endif
   195				}
   196			} while (mScriptTableIteratorNext(rootVal, &iter) && ok);
   197		}
   198		if (!ok) {
   199			json_object_put(rootObj);
   200			return NULL;
   201		}
   202		return rootObj;
   203	}
   204	
   205	bool mScriptStorageToJson(struct mScriptValue* value, struct json_object** out) {
   206		if (value->type->base == mSCRIPT_TYPE_WRAPPER) {
   207			value = mScriptValueUnwrap(value);
   208		}
   209	
   210		size_t i;
   211		bool ok = true;
   212		struct json_object* obj = NULL;
   213		switch (value->type->base) {
   214		case mSCRIPT_TYPE_SINT:
   215			obj = json_object_new_int64(value->value.s64);
   216			break;
   217		case mSCRIPT_TYPE_UINT:
   218			if (value->type == mSCRIPT_TYPE_MS_BOOL) {
   219				obj = json_object_new_boolean(value->value.u32);
   220				break;
   221			}
   222	#if JSON_C_VERSION_NUM >= (14 << 8)
   223			obj = json_object_new_uint64(value->value.u64);
   224	#else
   225			if (value->value.u64 < (uint64_t) INT64_MAX) {
   226				obj = json_object_new_int64(value->value.u64);
   227			} else {
   228				obj = json_object_new_double(value->value.u64);
   229			}
   230	#endif
   231			break;
   232		case mSCRIPT_TYPE_FLOAT:
   233			obj = json_object_new_double(value->value.f64);
   234			break;
   235		case mSCRIPT_TYPE_STRING:
   236			obj = json_object_new_string_len(value->value.string->buffer, value->value.string->size);
   237			break;
   238		case mSCRIPT_TYPE_LIST:
   239	#if JSON_C_VERSION_NUM >= (15 << 8)
   240			obj = json_object_new_array_ext(mScriptListSize(value->value.list));
   241	#else
   242			obj = json_object_new_array();
   243	#endif
   244			for (i = 0; i < mScriptListSize(value->value.list); ++i) {
   245				struct json_object* listObj;
   246				ok = mScriptStorageToJson(mScriptListGetPointer(value->value.list, i), &listObj);
   247				if (!ok) {
   248					break;
   249				}
   250				json_object_array_add(obj, listObj);
   251			}
   252			break;
   253		case mSCRIPT_TYPE_TABLE:
   254			obj = _tableToJson(value);
   255			if (!obj) {
   256				ok = false;
   257			}
   258			break;
   259		case mSCRIPT_TYPE_VOID:
   260			obj = NULL;
   261			break;
   262		default:
   263			ok = false;
   264			break;
   265		}
   266	
   267		if (!ok) {
   268			if (obj) {
   269				json_object_put(obj);
   270			}
   271			*out = NULL;
   272		} else {
   273			*out = obj;
   274		}
   275		return ok;
   276	}
