    82	static void _freeTable(void* data) {
    83		struct Table* table = data;
    84	
    85		struct TableIterator iter;
    86		if (TableIteratorStart(table, &iter)) {
    87			do {
    88				struct mScriptCallbackInfo* info = TableIteratorGetValue(table, &iter);
    89				mScriptValueDeref(info->fn);
    90			} while (TableIteratorNext(table, &iter));
    91		}
    92	
    93		TableDeinit(table);
    94		free(table);
    95	}
