   127	void mScriptContextFillPool(struct mScriptContext* context, struct mScriptValue* value) {
   128		if (value->refs == mSCRIPT_VALUE_UNREF) {
   129			return;
   130		}
   131	
   132		struct mScriptValue* poolEntry = mScriptListAppend(&context->refPool);
   133		poolEntry->type = mSCRIPT_TYPE_MS_WRAPPER;
   134		poolEntry->value.opaque = value;
   135		poolEntry->refs = mSCRIPT_VALUE_UNREF;
   136	}
   137	
   138	void mScriptContextDrainPool(struct mScriptContext* context) {
   139		size_t i;
   140		for (i = 0; i < mScriptListSize(&context->refPool); ++i) {
   141			struct mScriptValue* value = mScriptListGetPointer(&context->refPool, i);
   142			if (value->type->base == mSCRIPT_TYPE_WRAPPER) {
   143				value = mScriptValueUnwrap(value);
   144				mScriptValueDeref(value);
   145			} else if (value->type == mSCRIPT_TYPE_MS_WEAKREF) {
   146				mScriptContextClearWeakref(context, value->value.u32);
   147			}
   148		}
   149		mScriptListClear(&context->refPool);
   150	}
