   168	void mScriptContextSetGlobal(struct mScriptContext* context, const char* key, struct mScriptValue* value) {
   169		struct mScriptValue* oldValue = HashTableLookup(&context->rootScope, key);
   170		if (oldValue) {
   171			mScriptContextClearWeakref(context, oldValue->value.u32);
   172		}
   173		value = mScriptContextMakeWeakref(context, value);
   174		HashTableInsert(&context->rootScope, key, value);
   175		struct mScriptKVPair pair = {
   176			.key = key,
   177			.value = value
   178		};
   179		HashTableEnumerate(&context->engines, _contextAddGlobal, &pair);
   180	}
   181	
   182	struct mScriptValue* mScriptContextGetGlobal(struct mScriptContext* context, const char* key) {
   183		struct mScriptValue* weakref = HashTableLookup(&context->rootScope, key);
   184		if (!weakref) {
   185			return NULL;
   186		}
   187		return mScriptContextAccessWeakref(context, weakref);
   188	}
   189	
   190	void mScriptContextRemoveGlobal(struct mScriptContext* context, const char* key) {
   191		if (!HashTableLookup(&context->rootScope, key)) {
   192			return;
   193		}
   194		// Since _contextRemoveGlobal doesn't mutate |key|, this cast should be safe
   195		HashTableEnumerate(&context->engines, _contextRemoveGlobal, (char*) key);
   196		struct mScriptValue* oldValue = HashTableLookup(&context->rootScope, key);
   197		if (oldValue) {
   198			mScriptContextClearWeakref(context, oldValue->value.u32);
   199			HashTableRemove(&context->rootScope, key);
   200		}
   201	}
