   203	struct mScriptValue* mScriptContextEnsureGlobal(struct mScriptContext* context, const char* key, const struct mScriptType* type) {
   204		struct mScriptValue* value = mScriptContextGetGlobal(context, key);
   205		if (!value) {
   206			mScriptContextSetGlobal(context, key, mScriptValueAlloc(type));
   207			value = mScriptContextGetGlobal(context, key);
   208		}
   209		return value;
   210	}
