   282	static bool _mScriptStorageBucketFlushVF(struct mScriptStorageBucket* bucket, struct VFile* vf) {
   283		struct json_object* rootObj;
   284		bool ok = mScriptStorageToJson(bucket->root, &rootObj);
   285		if (!ok) {
   286			vf->close(vf);
   287			return false;
   288		}
   289	
   290		const char* json = json_object_to_json_string_ext(rootObj, JSON_C_TO_STRING_PRETTY | JSON_C_TO_STRING_PRETTY_TAB);
   291		if (!json) {
   292			json_object_put(rootObj);
   293			vf->close(vf);
   294			return false;
   295		}
   296	
   297		vf->write(vf, json, strlen(json));
   298		vf->close(vf);
   299	
   300		bucket->dirty = false;
   301	
   302		json_object_put(rootObj);
   303		return true;
   304	}
