 20	    """
 21	    Provides access to the frame buffer of PyBoy Advance.
 22	    """
 23	
 24	    def __init__(self, ppu: PPU):
 25	        self.ppu = ppu
 26	
 27	    @property
 28	    def ndarray(self) -> "np.ndarray":
 29	        """
 30	        Get the current frame buffer in a NumPy ``ndarray``.
 31	
 32	        :return: RGB image in ``ndarray`` of bytes with shape (160, 240, 3)
 33	        """
 34	        buffer_type = ctypes.POINTER(ctypes.c_uint16 * DISPLAY_HEIGHT * DISPLAY_WIDTH)
 35	        buffer = ctypes.cast(self.ppu.frame_buffer_ptr, buffer_type).contents
 36	        img_bgr555 = np.frombuffer(buffer, dtype=np.uint16).reshape((DISPLAY_HEIGHT, DISPLAY_WIDTH))
 37	
 38	        # Extract channels
 39	        b = (img_bgr555 >> 10) & 0x1F
 40	        g = (img_bgr555 >> 5) & 0x1F
 41	        r = img_bgr555 & 0x1F
 42	
 43	        # Scale 5-bit to 8-bit
 44	        r = (r * 255 // 31).astype(np.uint8)
 45	        g = (g * 255 // 31).astype(np.uint8)
 46	        b = (b * 255 // 31).astype(np.uint8)
 47	
 48	        return np.stack([r, g, b], axis=-1)
 49	
