 51	    def image(self) -> "PILImage.Image":
 52	        """
 53	        Get a PIL Image of the current frame buffer.
 54	
 55	        :return: RGB image of (240, 160) pixels
 56	        """
 57	        return PILImage.fromarray(self.ndarray, "RGB")
